<div class="card table-card"><table><thead><tr><th>SKU / สินค้า</th><th>ต้นทุน</th><th>ราคาขาย</th><th>ช่วงตลาด</th><th>คงเหลือ</th><th>อายุ</th><th>สถานะ</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><b><?= htmlspecialchars($i['sku']??'-') ?></b><small><?= htmlspecialchars($i['full_name']??$i['raw_product_name']) ?></small></td><td>฿<?= number_format((float)$i['cost_price']) ?></td><td>฿<?= number_format((float)$i['asking_price']) ?></td><td><?= $i['market_min']!==null && $i['market_max']!==null ? '฿'.number_format((float)$i['market_min']).'–฿'.number_format((float)$i['market_max']) : 'ข้อมูลตลาดยังไม่เพียงพอ' ?></td><td><?= (int)$i['quantity'] ?></td><td><?= (int)$i['age_days'] ?> วัน</td><td><span class="badge"><?= htmlspecialchars($i['status']) ?></span></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="7" class="empty-cell">ยังไม่มี inventory item</td></tr><?php endif; ?></tbody></table></div>
